logged();$song=$editing?get_song(song_id()):[];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();foreach(['title','artist','album','genre','release_year','duration','description'] as $k)$song[$k]=input_filter($_POST,$k);foreach(['title'=>255,'artist'=>255,'genre'=>100,'album'=>255,'description'=>10000] as $k=>$max){if(strlen($song[$k])>$max||($song[$k]===''&&in_array($k,['title','artist','genre'],true)))$error='Check required fields and field lengths.';}if(!preg_match('/^\d{4}$/D',$song['release_year'])||(int)$song['release_year']<1901||(int)$song['release_year']>2155)$error='Enter a year from 1901 to 2155.';if($song['duration']!==''&&!preg_match('/^\d{2}:[0-5]\d:[0-5]\d$/D',$song['duration']))$error='Duration must be HH:MM:SS.';if(!$error){$values=[];foreach(['title','artist','album','genre','release_year','duration','description'] as $k)$values[]=$song[$k]===''?null:$song[$k];if($editing){$values[]=$song['id'];$sql='UPDATE songs SET title=?,artist=?,album=?,genre=?,release_year=?,duration=?,description=? WHERE id=?';}else{$sql='INSERT INTO songs(title,artist,album,genre,release_year,duration,description) VALUES (?,?,?,?,?,?,?)';}$db->prepare($sql)->execute($values);redirect('list-songs.php');}}render('form.twig',['song'=>$song,'heading'=>$editing?'Edit song':'Add song','error'=>$error]);
